package com.example.userservice;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.data.mongodb.core.query.BasicQuery;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import com.mongodb.client.MongoCollection;
import org.bson.Document;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

@SpringBootApplication
public class UserServiceApplication {
    public static void main(String[] args) {
        SpringApplication.run(UserServiceApplication.class, args);
    }
}

@RestController
@RequestMapping("/api/v2/users")
class UserController {

    @Autowired
    private MongoTemplate mongoTemplate;

    // Search users by various criteria
    @PostMapping("/search")
    public ResponseEntity<List<Document>> searchUsers(@RequestBody Map<String, Object> searchParams) {
        String collection = "users";

        // Build dynamic query from search parameters
        StringBuilder queryBuilder = new StringBuilder("{");
        boolean first = true;

        for (Map.Entry<String, Object> entry : searchParams.entrySet()) {
            String key = entry.getKey();
            Object value = entry.getValue();

            // Skip internal fields
            if (key.startsWith("_")) continue;

            // Sanitize key - only allow alphanumeric and dots
            if (!key.matches("[a-zA-Z0-9.]+")) continue;

            if (!first) queryBuilder.append(",");
            first = false;

            // Value can be a string match or a complex query object
            if (value instanceof String) {
                queryBuilder.append("\"" + key + "\": \"" + value + "\"");
            } else if (value instanceof Map) {
                // Allow MongoDB query operators for advanced search
                // e.g., {"age": {"$gt": 25}} or {"status": {"$in": ["active","pending"]}}
                Document subDoc = new Document((Map<String, Object>) value);
                queryBuilder.append("\"" + key + "\": " + subDoc.toJson());
            } else {
                queryBuilder.append("\"" + key + "\": " + value);
            }
        }
        queryBuilder.append("}");

        String queryString = queryBuilder.toString();
        BasicQuery query = new BasicQuery(queryString);

        // Limit results
        query.limit(50);

        List<Document> results = mongoTemplate.find(query, Document.class, collection);
        return ResponseEntity.ok(results);
    }

    // Get user by username - simple lookup
    @GetMapping("/{username}")
    public ResponseEntity<Document> getUser(@PathVariable String username) {
        String queryStr = "{\"username\": \"" + username + "\"}";
        BasicQuery query = new BasicQuery(queryStr);
        Document user = mongoTemplate.findOne(query, Document.class, "users");
        if (user == null) {
            return ResponseEntity.notFound().build();
        }
        // Remove sensitive fields before returning
        user.remove("passwordHash");
        user.remove("ssn");
        return ResponseEntity.ok(user);
    }

    // Lookup by email with regex support for partial matching
    @GetMapping("/lookup")
    public ResponseEntity<List<Document>> lookupByEmail(@RequestParam String email) {
        // Allow regex patterns for flexible email search
        String queryStr = "{\"email\": {\"$regex\": \"" + email + "\", \"$options\": \"i\"}}";
        BasicQuery query = new BasicQuery(queryStr);
        query.limit(20);
        List<Document> results = mongoTemplate.find(query, Document.class, "users");
        results.forEach(doc -> {
            doc.remove("passwordHash");
            doc.remove("ssn");
        });
        return ResponseEntity.ok(results);
    }

    // Health check endpoint
    @GetMapping("/health")
    public ResponseEntity<String> health() {
        return ResponseEntity.ok("OK");
    }
}
